import{_ as t,c as a,o as r,ae as i}from"./chunks/framework.CliRSA9F.js";const o="/images/editorial_presence.webp",m=JSON.parse('{"title":"My Placements","description":"","frontmatter":{},"headers":[],"relativePath":"features/my-placements.md","filePath":"features/my-placements.md"}'),s={name:"features/my-placements.md"};function l(n,e,u,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="my-placements" tabindex="-1">My Placements <a class="header-anchor" href="#my-placements" aria-label="Permalink to &quot;My Placements&quot;">​</a></h1><h2 id="track-where-your-podcast-gets-featured" tabindex="-1">Track Where Your Podcast Gets Featured <a class="header-anchor" href="#track-where-your-podcast-gets-featured" aria-label="Permalink to &quot;Track Where Your Podcast Gets Featured&quot;">​</a></h2><p>My Placements shows you everywhere your podcast has been featured - from platform editorial lists to web links in newsletters, blogs, and curated recommendation sites. Understanding your editorial footprint helps you measure visibility and identify new opportunities.</p><p><img src="'+o+'" alt="My Placements Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h2 id="what-you-ll-see" tabindex="-1">What You&#39;ll See <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What You&#39;ll See&quot;">​</a></h2><h3 id="platform-editorial-features" tabindex="-1">Platform Editorial Features <a class="header-anchor" href="#platform-editorial-features" aria-label="Permalink to &quot;Platform Editorial Features&quot;">​</a></h3><p>Track your podcast&#39;s appearances in curated editorial content across:</p><ul><li><strong>Apple Podcasts</strong> - New &amp; Noteworthy, editorial collections, category features</li><li><strong>Spotify</strong> - Editorial playlists, featured sections, genre highlights</li><li><strong>Amazon Music</strong> - Curated recommendations and platform features</li><li><strong>YouTube Music</strong> - Featured podcast placements</li></ul><p>For each platform, you&#39;ll see:</p><ul><li><strong>Currently Featured</strong> - Editorial lists where your podcast appears now</li><li><strong>Recently Featured</strong> - Lists your podcast was on recently but no longer appears on</li><li><strong>Historical appearances</strong> - Your complete editorial history on that platform</li></ul><h3 id="web-links-pro-feature" tabindex="-1">Web Links (Pro Feature) <a class="header-anchor" href="#web-links-pro-feature" aria-label="Permalink to &quot;Web Links (Pro Feature)&quot;">​</a></h3><p>Beyond platform editorial, Pro users can track web links - pages across the web where your podcast is recommended on websites, newsletters, blogs, and curated lists.</p><p>Web links show:</p><ul><li><strong>Domain count</strong> - How many different websites mention your podcast</li><li><strong>Page count</strong> - Total pages where your podcast appears</li><li><strong>Domain authority</strong> - Quality indicators for each source (Very High, High, Medium)</li><li><strong>Top domains</strong> - Your most authoritative web placements</li></ul><p>High-authority web links from reputable sites can influence both listener trust and AI recommendations.</p><p>You can also add a link yourself. Use the <strong>Submit</strong> button on the Web Links card to open a form where you can submit the URL of a page that mentions your podcast, so it can be matched into your web links.</p><h2 id="understanding-the-metrics" tabindex="-1">Understanding the Metrics <a class="header-anchor" href="#understanding-the-metrics" aria-label="Permalink to &quot;Understanding the Metrics&quot;">​</a></h2><h3 id="currently-featured-vs-recently-dropped" tabindex="-1">Currently Featured vs. Recently Dropped <a class="header-anchor" href="#currently-featured-vs-recently-dropped" aria-label="Permalink to &quot;Currently Featured vs. Recently Dropped&quot;">​</a></h3><p><strong>Currently Featured</strong> shows editorial placements that are active right now. These represent ongoing visibility that&#39;s driving discovery.</p><p><strong>Recently Dropped</strong> (labeled <strong>Recently Featured</strong> in the Platform editorial card list) tracks lists your podcast was on recently but no longer appears on. Reviewing these helps you:</p><ul><li>Understand editorial rotation patterns</li><li>Measure how long features typically last</li><li>Identify when to pursue new opportunities</li></ul><h3 id="domain-authority" tabindex="-1">Domain Authority <a class="header-anchor" href="#domain-authority" aria-label="Permalink to &quot;Domain Authority&quot;">​</a></h3><p>Web links are categorized by domain authority:</p><ul><li><strong>Very High</strong> - Major publications, well-known podcasting sites</li><li><strong>High</strong> - Established blogs, industry newsletters, respected directories</li><li><strong>Medium</strong> - Smaller sites, niche publications, personal recommendations</li></ul><p>Higher authority sources carry more weight for discoverability and credibility.</p><h2 id="strategic-applications" tabindex="-1">Strategic Applications <a class="header-anchor" href="#strategic-applications" aria-label="Permalink to &quot;Strategic Applications&quot;">​</a></h2><h3 id="measure-editorial-success" tabindex="-1">Measure Editorial Success <a class="header-anchor" href="#measure-editorial-success" aria-label="Permalink to &quot;Measure Editorial Success&quot;">​</a></h3><p>Track your editorial presence over time to understand:</p><ul><li>Which platforms feature you most often</li><li>How long your editorial placements typically last</li><li>Whether your editorial visibility is growing</li></ul><h3 id="identify-patterns" tabindex="-1">Identify Patterns <a class="header-anchor" href="#identify-patterns" aria-label="Permalink to &quot;Identify Patterns&quot;">​</a></h3><p>Analyze your editorial history to spot patterns:</p><ul><li>Content types or themes that attract editorial attention</li><li>Timing patterns (seasonal trends, launch momentum)</li><li>Platforms where you have the strongest editorial relationship</li></ul><h3 id="build-on-web-links" tabindex="-1">Build on Web Links <a class="header-anchor" href="#build-on-web-links" aria-label="Permalink to &quot;Build on Web Links&quot;">​</a></h3><p>Use web link data to:</p><ul><li>Discover sites that feature podcasts like yours</li><li>Reach out to publications that already know your show</li><li>Prioritize outreach to high-authority domains</li></ul><h2 id="requesting-editorial-features" tabindex="-1">Requesting Editorial Features <a class="header-anchor" href="#requesting-editorial-features" aria-label="Permalink to &quot;Requesting Editorial Features&quot;">​</a></h2><p>If you want to increase your editorial presence, you can use PodSEO&#39;s <a href="/features/pr-outreach.html">PR Outreach</a> pipeline to manage the process. Click <strong>Find Opportunities</strong> in PR Outreach to load a curated list of pitch targets — platform editorial submission pages (such as Apple Podcasts and Spotify) along with podcast newsletters, directories, and blogs worth pitching — then add them to your kanban board and track your submissions through the pipeline stages from Identified to Featured.</p><p>For Apple Podcasts specifically:</p><ol><li>Visit Apple&#39;s <a href="https://airtable.com/appL7FlZuT3KbtUz0/pagX0sfhAxqSB6zp4/form" target="_blank" rel="noreferrer">feature request form</a></li><li>Follow their <a href="https://podcasters.apple.com/support/1993-optimize-your-request-for-promotion" target="_blank" rel="noreferrer">optimization guide</a></li><li>Submit at least 2 weeks before your desired feature date</li><li>Prepare special <a href="https://podcasters.apple.com/asset/show-hero-template.zip" target="_blank" rel="noreferrer">feature artwork</a> if required</li></ol><p>Tips for successful requests:</p><ul><li>Highlight what makes your content unique and timely</li><li>Explain your promotional plans to amplify the feature</li><li>Ensure your podcast meets platform quality standards</li><li>Consider timing around significant episodes or milestones</li></ul><h2 id="connection-to-other-features" tabindex="-1">Connection to Other Features <a class="header-anchor" href="#connection-to-other-features" aria-label="Permalink to &quot;Connection to Other Features&quot;">​</a></h2><p>My Placements works alongside other PodSEO discovery features:</p><ul><li><strong><a href="/features/pr-outreach.html">PR Outreach</a></strong> - Actively earn the web mentions and listicle placements this page tracks; because AI assistants weigh website recommendations heavily, this pipeline drives both editorial and AI visibility</li><li><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> - Track AI recommendation visibility; the high-authority web links here are exactly the sources AI assistants draw on</li><li><strong>Curated Lists</strong> - Browse what platforms are promoting across all podcasts</li><li><strong>All Charts</strong> - Monitor chart rankings for another view of platform visibility</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Platform editorial tracking is available to all users. Web links with domain authority data require a Pro subscription.</p><p><strong>Related Features</strong>: Use <a href="/features/curated-lists.html">Curated Lists</a> to research platform editorial content, and check <a href="/features/all-charts.html">All Charts</a> to see chart rankings alongside editorial visibility.</p>',47)])])}const y=t(s,[["render",l]]);export{m as __pageData,y as default};
